import { ethers } from 'ethers';
const RPC = 'https://rpc.mainnet.chain.robinhood.com';
const p = new ethers.JsonRpcProvider(RPC, undefined, { headers: { 'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36' } });
const FOIL = '0x6573682faee72a4a96e791ba262439f1df3a268d';
const NFT = '0xc616b36c9194d8fdacf97e9a3b9c250e0b81b70e';
const nft = new ethers.Contract(NFT, ['function totalSupply() view returns (uint256)', 'function maxSupply() view returns (uint256)', 'function balanceOf(address) view returns (uint256)'], p);
try {
  const [bal, ts] = await Promise.all([p.getBalance(FOIL), nft.totalSupply().catch(()=>'?')]);
  let ms = '?'; try { ms = (await nft.maxSupply()).toString(); } catch(e){}
  const foilNfts = await nft.balanceOf(FOIL).catch(()=>'?');
  console.log('foil RH ETH:', ethers.formatEther(bal), '| totalSupply:', ts.toString(), '| maxSupply:', ms, '| foil nodebots:', foilNfts.toString());
  const gp = await p.getFeeData();
  console.log('gasPrice:', ethers.formatUnits(gp.gasPrice, 'gwei'), 'gwei');
} catch(e) { console.log('ERR', e.message.slice(0,200)); }
EOF

